use anyhow::{anyhow, Result};
use corridor_core::contract::{ContractHasher, ContractKind, ExportedSymbolContract};
use oxc_allocator::Allocator;
use oxc_ast::ast::{Declaration, Statement};
use oxc_parser::Parser;
use oxc_span::{GetSpan, SourceType, Span};
use std::path::Path;

#[derive(Debug, Clone)]
pub struct ExtractedTsSymbol {
    pub name: String,
    pub byte_range: (usize, usize),
    pub line_range: (usize, usize),
    pub is_exported: bool,
    pub is_contract: bool,
    pub mutates_state: bool,
    pub signature_hash: String,
}

pub struct TsAstSlicer;

impl TsAstSlicer {
    /// Parses a TypeScript file using oxc and extracts all top-level exported/internal declarations
    /// along with their exact byte ranges and contract hashes.
    pub fn analyze_file(file_path: &Path, source_text: &str) -> Result<Vec<ExtractedTsSymbol>> {
        let allocator = Allocator::default();
        let source_type = SourceType::from_path(file_path).unwrap_or_default().with_typescript(true);
        let ret = Parser::new(&allocator, source_text, source_type).parse();

        let line_starts = Self::compute_line_starts(source_text);
        let mut symbols = Vec::new();

        for stmt in &ret.program.body {
            match stmt {
                Statement::ExportNamedDeclaration(export_decl) => {
                    if let Some(decl) = &export_decl.declaration {
                        if let Some(sym) = Self::extract_declaration(
                            decl,
                            export_decl.span,
                            true,
                            source_text,
                            &line_starts,
                        ) {
                            symbols.push(sym);
                        }
                    }
                }
                _ => {
                    if let Some(decl) = stmt.as_declaration() {
                        if let Some(sym) = Self::extract_declaration(
                            decl,
                            stmt.span(),
                            false,
                            source_text,
                            &line_starts,
                        ) {
                            symbols.push(sym);
                        }
                    }
                }
            }
        }

        Ok(symbols)
    }

    /// Extracts all exported contracts from a TypeScript file for before/after mutation comparison.
    pub fn extract_exported_contracts(
        file_path: &Path,
        source_text: &str,
    ) -> Result<Vec<ExportedSymbolContract>> {
        let allocator = Allocator::default();
        let source_type = SourceType::from_path(file_path).unwrap_or_default().with_typescript(true);
        let ret = Parser::new(&allocator, source_text, source_type).parse();

        if !ret.errors.is_empty() {
            let err_msgs: Vec<String> = ret.errors.iter().map(|e| e.to_string()).collect();
            return Err(anyhow!("Syntax error during AST parse: {}", err_msgs.join("; ")));
        }

        let mut contracts = Vec::new();
        for stmt in &ret.program.body {
            if let Statement::ExportNamedDeclaration(export_decl) = stmt {
                if let Some(decl) = &export_decl.declaration {
                    match decl {
                        Declaration::TSInterfaceDeclaration(iface) => {
                            let name = iface.id.name.to_string();
                            let raw_slice = &source_text[iface.span.start as usize..iface.span.end as usize];
                            let hash = blake3::hash(raw_slice.as_bytes()).to_hex().to_string();
                            contracts.push(ExportedSymbolContract {
                                symbol_name: name,
                                kind: ContractKind::Interface,
                                normalized_signature: raw_slice.to_string(),
                                signature_hash: hash,
                            });
                        }
                        Declaration::TSTypeAliasDeclaration(alias) => {
                            let name = alias.id.name.to_string();
                            let raw_slice = &source_text[alias.span.start as usize..alias.span.end as usize];
                            let hash = blake3::hash(raw_slice.as_bytes()).to_hex().to_string();
                            contracts.push(ExportedSymbolContract {
                                symbol_name: name,
                                kind: ContractKind::TypeAlias,
                                normalized_signature: raw_slice.to_string(),
                                signature_hash: hash,
                            });
                        }
                        Declaration::FunctionDeclaration(func) => {
                            if let Some(id) = &func.id {
                                let name = id.name.to_string();
                                // Hash strictly the header (parameters + return type), excluding body
                                let body_start = func
                                    .body
                                    .as_ref()
                                    .map(|b| b.span.start as usize)
                                    .unwrap_or(func.span.end as usize);
                                let header_slice = &source_text[func.span.start as usize..body_start];
                                let hash = blake3::hash(header_slice.as_bytes()).to_hex().to_string();
                                contracts.push(ExportedSymbolContract {
                                    symbol_name: name,
                                    kind: ContractKind::FunctionSignature,
                                    normalized_signature: header_slice.to_string(),
                                    signature_hash: hash,
                                });
                            }
                        }
                        Declaration::ClassDeclaration(cls) => {
                            if let Some(id) = &cls.id {
                                let name = id.name.to_string();
                                let raw_slice = &source_text[cls.span.start as usize..cls.span.end as usize];
                                let hash = blake3::hash(raw_slice.as_bytes()).to_hex().to_string();
                                contracts.push(ExportedSymbolContract {
                                    symbol_name: name.clone(),
                                    kind: ContractKind::ClassPublicSurface,
                                    normalized_signature: name,
                                    signature_hash: hash,
                                });
                            }
                        }
                        _ => {}
                    }
                }
            }
        }

        Ok(contracts)
    }

    pub fn compute_file_contract_hash(file_path: &Path, source_text: &str) -> Result<String> {
        let contracts = Self::extract_exported_contracts(file_path, source_text)?;
        Ok(ContractHasher::hash_normalized_surface(&contracts))
    }

    pub fn slice_lines(source_text: &str, start_line: usize, end_line: usize) -> String {
        let lines: Vec<&str> = source_text.lines().collect();
        if lines.is_empty() {
            return String::new();
        }
        let s = start_line.saturating_sub(1).min(lines.len().saturating_sub(1));
        let e = end_line.min(lines.len());
        lines[s..e]
            .iter()
            .enumerate()
            .map(|(idx, line)| format!("{:4} | {}", s + idx + 1, line))
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn extract_declaration(
        decl: &Declaration,
        outer_span: Span,
        is_exported: bool,
        source_text: &str,
        line_starts: &[usize],
    ) -> Option<ExtractedTsSymbol> {
        let start = outer_span.start as usize;
        let end = outer_span.end as usize;
        let slice = &source_text[start..end.min(source_text.len())];
        let line_range = (
            Self::byte_to_line(line_starts, start),
            Self::byte_to_line(line_starts, end),
        );

        let mutates_state = slice.contains(".save(")
            || slice.contains(".insert(")
            || slice.contains(".update(")
            || slice.contains(".delete(")
            || slice.contains("prisma.")
            || slice.contains(" dispatch(");

        match decl {
            Declaration::TSInterfaceDeclaration(iface) => Some(ExtractedTsSymbol {
                name: iface.id.name.to_string(),
                byte_range: (start, end),
                line_range,
                is_exported,
                is_contract: true,
                mutates_state: false,
                signature_hash: blake3::hash(slice.as_bytes()).to_hex().to_string(),
            }),
            Declaration::TSTypeAliasDeclaration(alias) => Some(ExtractedTsSymbol {
                name: alias.id.name.to_string(),
                byte_range: (start, end),
                line_range,
                is_exported,
                is_contract: true,
                mutates_state: false,
                signature_hash: blake3::hash(slice.as_bytes()).to_hex().to_string(),
            }),
            Declaration::FunctionDeclaration(func) => {
                let name = func.id.as_ref()?.name.to_string();
                Some(ExtractedTsSymbol {
                    name,
                    byte_range: (start, end),
                    line_range,
                    is_exported,
                    is_contract: false,
                    mutates_state,
                    signature_hash: blake3::hash(slice.as_bytes()).to_hex().to_string(),
                })
            }
            Declaration::ClassDeclaration(cls) => {
                let name = cls.id.as_ref()?.name.to_string();
                Some(ExtractedTsSymbol {
                    name,
                    byte_range: (start, end),
                    line_range,
                    is_exported,
                    is_contract: false,
                    mutates_state,
                    signature_hash: blake3::hash(slice.as_bytes()).to_hex().to_string(),
                })
            }
            _ => None,
        }
    }

    fn compute_line_starts(source: &str) -> Vec<usize> {
        let mut starts = vec![0];
        for (i, b) in source.bytes().enumerate() {
            if b == b'\n' {
                starts.push(i + 1);
            }
        }
        starts
    }

    fn byte_to_line(line_starts: &[usize], byte_offset: usize) -> usize {
        match line_starts.binary_search(&byte_offset) {
            Ok(idx) => idx + 1,
            Err(idx) => idx,
        }
    }
}

use crate::ast_slicer::TsAstSlicer;
use anyhow::{Context, Result};
use corridor_core::graph::{CodebaseGraph, EdgeKind, NodeRole, SemanticEdge, SemanticNode};
use protobuf::Message;
use scip::types::{Index as ScipIndex, SymbolRole};
use std::collections::HashMap;
use std::fs;
use std::path::Path;

pub struct ScipGraphBuilder;

impl ScipGraphBuilder {
    /// Loads a `index.scip` protobuf file generated by `npx @sourcegraph/scip-typescript index`
    /// and builds a complete Cross-File CodebaseGraph.
    pub fn build_from_scip_file(workspace_root: &Path, scip_path: &Path) -> Result<CodebaseGraph> {
        let raw_bytes = fs::read(scip_path)
            .with_context(|| format!("Failed to read SCIP index at {}", scip_path.display()))?;
        let scip_index = ScipIndex::parse_from_bytes(&raw_bytes)
            .context("Failed to decode SCIP protobuf payload")?;

        let mut graph = CodebaseGraph::new();
        let mut file_symbol_Owner_ranges: HashMap<String, Vec<(usize, usize, String)>> = HashMap::new();

        // Pass 1: Register all Symbol Definitions across all indexed documents
        for doc in &scip_index.documents {
            let rel_path = doc.relative_path.clone();
            let abs_path = workspace_root.join(&rel_path);
            let source_text = fs::read_to_string(&abs_path).unwrap_or_default();
            let ast_symbols = TsAstSlicer::analyze_file(&abs_path, &source_text).unwrap_or_default();

            for occ in &doc.occurrences {
                let is_definition = (occ.symbol_roles & (SymbolRole::Definition as i32)) != 0;
                if !is_definition || occ.symbol.starts_with("local ") {
                    continue;
                }

                let start_line = occ.range.first().copied().unwrap_or(0) as usize + 1;
                let matched_ast = ast_symbols
                    .iter()
                    .find(|s| start_line >= s.line_range.0 && start_line <= s.line_range.1);

                let (byte_range, line_range, role, sig_hash, mutates, is_exp) =
                    if let Some(ast_sym) = matched_ast {
                        let inferred_role = Self::classify_role(&rel_path, &occ.symbol, ast_sym.is_contract, ast_sym.mutates_state);
                        (
                            ast_sym.byte_range,
                            ast_sym.line_range,
                            inferred_role,
                            ast_sym.signature_hash.clone(),
                            ast_sym.mutates_state,
                            ast_sym.is_exported,
                        )
                    } else {
                        let role = Self::classify_role(&rel_path, &occ.symbol, false, false);
                        (
                            (0, 0),
                            (start_line, start_line + 20),
                            role,
                            blake3::hash(occ.symbol.as_bytes()).to_hex().to_string(),
                            false,
                            true,
                        )
                    };

                let node = SemanticNode {
                    symbol_id: occ.symbol.clone(),
                    display_name: Self::short_display_name(&occ.symbol),
                    file_path: rel_path.clone(),
                    byte_range,
                    line_range,
                    role,
                    signature_hash: sig_hash,
                    mutates_domain_state: mutates,
                    is_exported: is_exp,
                };

                graph.upsert_node(node);
                file_symbol_Owner_ranges
                    .entry(rel_path.clone())
                    .or_default()
                    .push((line_range.0, line_range.1, occ.symbol.clone()));
            }
        }

        // Pass 2: Connect Cross-File Reference Edges
        for doc in &scip_index.documents {
            let rel_path = &doc.relative_path;
            let owners = match file_symbol_Owner_ranges.get(rel_path) {
                Some(list) => list,
                None => continue,
            };

            for occ in &doc.occurrences {
                let is_definition = (occ.symbol_roles & (SymbolRole::Definition as i32)) != 0;
                if is_definition || occ.symbol.starts_with("local ") {
                    continue;
                }

                if !graph.symbol_to_index.contains_key(&occ.symbol) {
                    continue;
                }

                let ref_line = occ.range.first().copied().unwrap_or(0) as usize + 1;
                if let Some((_, _, caller_symbol)) = owners
                    .iter()
                    .find(|(s_line, e_line, _)| ref_line >= *s_line && ref_line <= *e_line)
                {
                    if caller_symbol != &occ.symbol {
                        let target_idx = graph.symbol_to_index[&occ.symbol];
                        let target_role = graph.graph[target_idx].role;
                        let edge_kind = if target_role == NodeRole::ContractDefinition {
                            EdgeKind::ReferencesType
                        } else if (occ.symbol_roles & (SymbolRole::WriteAccess as i32)) != 0 {
                            EdgeKind::MutatesState
                        } else {
                            EdgeKind::Calls
                        };

                        graph.add_edge(
                            caller_symbol,
                            &occ.symbol,
                            SemanticEdge {
                                kind: edge_kind,
                                call_site_line: ref_line,
                                is_dynamic_trace: false,
                            },
                        );
                    }
                }
            }
        }

        Ok(graph)
    }

    fn classify_role(
        rel_path: &str,
        symbol: &str,
        is_contract: bool,
        mutates_state: bool,
    ) -> NodeRole {
        if is_contract || rel_path.ends_with(".types.ts") || rel_path.ends_with(".dto.ts") {
            NodeRole::ContractDefinition
        } else if rel_path.contains(".controller.")
            || rel_path.contains("/routes/")
            || symbol.contains("Controller")
            || symbol.contains("Handler")
        {
            NodeRole::EntryGate
        } else if rel_path.contains(".repository.")
            || rel_path.contains(".dao.")
            || mutates_state
        {
            NodeRole::DataRepository
        } else if rel_path.contains("/utils/")
            || rel_path.contains("/logger/")
            || rel_path.contains("/helpers/")
        {
            NodeRole::UtilityNoise
        } else {
            NodeRole::BusinessLogic
        }
    }

    fn short_display_name(scip_symbol: &str) -> String {
        scip_symbol
            .split('/')
            .next_back()
            .unwrap_or(scip_symbol)
            .to_string()
    }
}

use anyhow::Result;
use oxc_allocator::Allocator;
use oxc_parser::Parser;
use oxc_span::SourceType;
use std::path::Path;
use std::process::Command;

pub struct TsGateVerifier;

impl TsGateVerifier {
    /// Tier 1 (<2ms): Fast AST syntax check via oxc_parser.
    /// Tier 2 (Optional): Runs incremental `tsc --noEmit` filtered to the target file.
    pub fn verify_gate_edit(
        workspace_root: &Path,
        relative_file_path: &str,
        proposed_source: &str,
        run_full_typecheck: bool,
    ) -> Result<Vec<String>> {
        let mut diagnostics = Vec::new();
        let file_path = workspace_root.join(relative_file_path);

        // Tier 1: OXC ultra-fast syntax validation
        let allocator = Allocator::default();
        let source_type = SourceType::from_path(&file_path)
            .unwrap_or_default()
            .with_typescript(true);
        let parse_res = Parser::new(&allocator, proposed_source, source_type).parse();

        for err in parse_res.errors {
            diagnostics.push(format!("[Syntax Error] {}: {}", relative_file_path, err));
        }

        if !diagnostics.is_empty() || !run_full_typecheck {
            return Ok(diagnostics);
        }

        // Tier 2: Incremental tsc check filtered to the active gate file
        let output = Command::new("npx")
            .arg("tsc")
            .arg("--noEmit")
            .arg("--pretty")
            .arg("false")
            .current_dir(workspace_root)
            .output();

        if let Ok(out) = output {
            if !out.status.success() {
                let stdout = String::from_utf8_lossy(&out.stdout);
                for line in stdout.lines() {
                    if line.starts_with(relative_file_path) {
                        diagnostics.push(format!("[Type Error] {}", line));
                    }
                }
            }
        }

        Ok(diagnostics)
    }
}

use anyhow::{anyhow, Result};
use corridor_core::graph::{CodebaseGraph, NodeRole};
use corridor_core::pruning::PruningConfig;
use corridor_core::slicer::{CorridorSlicer, GateStatus, SliceIntent};
use corridor_core::state::CorridorSession;
use corridor_ts_bridge::ast_slicer::TsAstSlicer;
use corridor_ts_bridge::verifier::TsGateVerifier;
use serde_json::{json, Value};
use std::fs;
use std::path::PathBuf;

pub struct CorridorMcpEngine {
    pub workspace_root: PathBuf,
    pub graph: CodebaseGraph,
    pub session: Option<CorridorSession>,
    pub run_tsc_on_advance: bool,
}

impl CorridorMcpEngine {
    pub fn new(workspace_root: PathBuf, graph: CodebaseGraph, run_tsc_on_advance: bool) -> Self {
        Self {
            workspace_root,
            graph,
            session: None,
            run_tsc_on_advance,
        }
    }

    pub fn list_tool_definitions() -> Value {
        json!({
            "tools": [
                {
                    "name": "corridor_discover_entrypoints",
                    "description": "Lists Entry Gates (HTTP routes, controllers, CLI handlers) in the repository without dumping file contents.",
                    "inputSchema": {
                        "type": "object",
                        "properties": {
                            "filter": { "type": "string", "description": "Optional substring filter for symbol or file path" }
                        }
                    }
                },
                {
                    "name": "corridor_open",
                    "description": "Initializes a strict refactoring/reading corridor state machine and unlocks Gate 0.",
                    "inputSchema": {
                        "type": "object",
                        "required": ["entry_symbol", "intent"],
                        "properties": {
                            "entry_symbol": { "type": "string", "description": "Exact symbol_id of the Entry Gate" },
                            "intent": { "type": "string", "enum": ["READ_FLOW", "MUTATE_CONTRACT"] },
                            "target_mutation_symbol": { "type": "string", "description": "Required when intent is MUTATE_CONTRACT" }
                        }
                    }
                },
                {
                    "name": "corridor_inspect_gate",
                    "description": "Returns the exact source code slice, upstream contracts, and Blast Radius report for an UNLOCKED gate. Rejects LOCKED future gates.",
                    "inputSchema": {
                        "type": "object",
                        "required": ["gate_index"],
                        "properties": {
                            "gate_index": { "type": "integer" }
                        }
                    }
                },
                {
                    "name": "corridor_propose_edit",
                    "description": "Applies an edit to the active gate, hashes exported TypeScript contracts to detect mutations, and runs syntax/type diagnostics.",
                    "inputSchema": {
                        "type": "object",
                        "required": ["gate_index", "new_file_content"],
                        "properties": {
                            "gate_index": { "type": "integer" },
                            "new_file_content": { "type": "string" },
                            "acknowledge_blast_radius": { "type": "boolean", "default": false }
                        }
                    }
                },
                {
                    "name": "corridor_advance_gate",
                    "description": "Verifies that the active gate compiles and has no unacknowledged cross-corridor contagion, then locks it and unlocks Gate N+1.",
                    "inputSchema": {
                        "type": "object",
                        "properties": {}
                    }
                },
                {
                    "name": "corridor_abort_or_rollback",
                    "description": "Reverts file modifications back to a specific gate checkpoint and restores gate locks.",
                    "inputSchema": {
                        "type": "object",
                        "required": ["to_gate_index"],
                        "properties": {
                            "to_gate_index": { "type": "integer" }
                        }
                    }
                }
            ]
        })
    }

    pub fn dispatch_tool(&mut self, name: &str, args: &Value) -> Result<String> {
        match name {
            "corridor_discover_entrypoints" => self.tool_discover_entrypoints(args),
            "corridor_open" => self.tool_open(args),
            "corridor_inspect_gate" => self.tool_inspect_gate(args),
            "corridor_propose_edit" => self.tool_propose_edit(args),
            "corridor_advance_gate" => self.tool_advance_gate(),
            "corridor_abort_or_rollback" => self.tool_rollback(args),
            _ => Err(anyhow!("Unknown Corridor MCP tool: {}", name)),
        }
    }

    fn tool_discover_entrypoints(&self, args: &Value) -> Result<String> {
        let filter = args
            .get("filter")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_lowercase();

        let mut entrypoints = Vec::new();
        for idx in self.graph.graph.node_indices() {
            let node = &self.graph.graph[idx];
            if node.role == NodeRole::EntryGate
                || (filter.len() > 2 && node.symbol_id.to_lowercase().contains(&filter))
            {
                if filter.is_empty()
                    || node.symbol_id.to_lowercase().contains(&filter)
                    || node.file_path.to_lowercase().contains(&filter)
                {
                    entrypoints.push(json!({
                        "symbol_id": node.symbol_id,
                        "display_name": node.display_name,
                        "file_path": node.file_path,
                        "line_range": node.line_range,
                        "role": node.role
                    }));
                }
            }
        }

        Ok(serde_json::to_string_pretty(&json!({
            "entrypoints_count": entrypoints.len(),
            "entrypoints": entrypoints
        }))?)
    }

    fn tool_open(&mut self, args: &Value) -> Result<String> {
        let entry_symbol = args
            .get("entry_symbol")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow!("Missing required argument: entry_symbol"))?;

        let intent_str = args
            .get("intent")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow!("Missing required argument: intent"))?;

        let intent = match intent_str {
            "READ_FLOW" => SliceIntent::ReadFlow,
            "MUTATE_CONTRACT" => SliceIntent::MutateContract,
            _ => return Err(anyhow!("Invalid intent '{}'. Use READ_FLOW or MUTATE_CONTRACT", intent_str)),
        };

        let target_mutation = args.get("target_mutation_symbol").and_then(|v| v.as_str());
        let config = PruningConfig::default();

        let plan = CorridorSlicer::build_corridor(
            &self.graph,
            entry_symbol,
            intent,
            target_mutation,
            &config,
        )?;

        let session = CorridorSession::new(self.workspace_root.clone(), plan);
        let state_file = self.workspace_root.join(".corridor/active_session.json");
        let _ = session.save_to_disk(&state_file);

        // Build token-efficient roadmap summary (hiding locked code)
        let gate_summaries: Vec<Value> = session
            .plan
            .gates
            .iter()
            .map(|g| {
                json!({
                    "gate_index": g.gate_index,
                    "status": g.status,
                    "symbol_id": g.node.symbol_id,
                    "file_path": g.node.file_path,
                    "role": g.node.role,
                    "blast_radius_risk": g.blast_radius.risk_level,
                    "external_dependents_count": g.blast_radius.contagion_index
                })
            })
            .collect();

        let corridor_id = session.plan.corridor_id.clone();
        let pruned_count = session.plan.pruned_nodes.len();
        self.session = Some(session);

        let gate_zero_view = self.tool_inspect_gate(&json!({ "gate_index": 0 }))?;

        Ok(serde_json::to_string_pretty(&json!({
            "corridor_id": corridor_id,
            "noise_nodes_pruned": pruned_count,
            "corridor_roadmap": gate_summaries,
            "active_gate_0_detail": serde_json::from_str::<Value>(&gate_zero_view).unwrap_or(Value::Null)
        }))?)
    }

    fn tool_inspect_gate(&self, args: &Value) -> Result<String> {
        let session = self
            .session
            .as_ref()
            .ok_or_else(|| anyhow!("No active corridor session. Call corridor_open first."))?;

        let gate_index = args
            .get("gate_index")
            .and_then(|v| v.as_u64())
            .ok_or_else(|| anyhow!("Missing integer gate_index"))? as usize;

        let gate = session.inspect_gate(gate_index)?;
        let abs_path = self.workspace_root.join(&gate.node.file_path);
        let full_source = fs::read_to_string(&abs_path).unwrap_or_default();
        let code_slice = TsAstSlicer::slice_lines(
            &full_source,
            gate.node.line_range.0,
            gate.node.line_range.1,
        );

        Ok(serde_json::to_string_pretty(&json!({
            "gate_index": gate.gate_index,
            "status": gate.status,
            "symbol_id": gate.node.symbol_id,
            "file_path": gate.node.file_path,
            "line_range": gate.node.line_range,
            "role": gate.node.role,
            "upstream_contracts": gate.upstream_contracts,
            "downstream_in_corridor": gate.downstream_in_corridor,
            "blast_radius": gate.blast_radius,
            "source_slice": code_slice
        }))?)
    }

    fn tool_propose_edit(&mut self, args: &Value) -> Result<String> {
        let session = self
            .session
            .as_mut()
            .ok_or_else(|| anyhow!("No active corridor session."))?;

        let gate_index = args
            .get("gate_index")
            .and_then(|v| v.as_u64())
            .ok_or_else(|| anyhow!("Missing gate_index"))? as usize;

        let new_content = args
            .get("new_file_content")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow!("Missing new_file_content"))?;

        let ack_blast = args
            .get("acknowledge_blast_radius")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let rel_path = session
            .plan
            .gates
            .get(gate_index)
            .ok_or_else(|| anyhow!("Invalid gate_index"))?
            .node
            .file_path
            .clone();

        let abs_path = self.workspace_root.join(&rel_path);
        let original_content = session
            .checkpoints
            .get(&gate_index)
            .map(|c| c.original_content.clone())
            .unwrap_or_else(|| fs::read_to_string(&abs_path).unwrap_or_default());

        let pre_hash = TsAstSlicer::compute_file_contract_hash(&abs_path, &original_content)
            .unwrap_or_else(|_| "invalid_pre_ast".to_string());

        // Write proposed edit to working tree so incremental verifier can inspect it
        fs::write(&abs_path, new_content)?;

        let post_hash = TsAstSlicer::compute_file_contract_hash(&abs_path, new_content)
            .unwrap_or_else(|_| "syntax_error_post_ast".to_string());

        let diagnostics = TsGateVerifier::verify_gate_edit(
            &self.workspace_root,
            &rel_path,
            new_content,
            self.run_tsc_on_advance,
        )?;

        session.record_proposed_edit(
            gate_index,
            original_content,
            new_content.to_string(),
            pre_hash.clone(),
            post_hash.clone(),
            diagnostics.clone(),
            ack_blast,
        )?;

        let state_file = self.workspace_root.join(".corridor/active_session.json");
        let _ = session.save_to_disk(&state_file);

        Ok(serde_json::to_string_pretty(&json!({
            "gate_index": gate_index,
            "file_path": rel_path,
            "contract_mutated": pre_hash != post_hash,
            "pre_contract_hash": pre_hash,
            "post_contract_hash": post_hash,
            "diagnostics_clean": diagnostics.is_empty(),
            "diagnostics": diagnostics,
            "next_step": if diagnostics.is_empty() {
                "Call `corridor_advance_gate` to lock this gate and unlock the next one."
            } else {
                "Fix the reported diagnostics in this gate and call `corridor_propose_edit` again."
            }
        }))?)
    }

    fn tool_advance_gate(&mut self) -> Result<String> {
        let session = self
            .session
            .as_mut()
            .ok_or_else(|| anyhow!("No active corridor session."))?;

        let new_phase = session.advance_gate()?;
        let state_file = self.workspace_root.join(".corridor/active_session.json");
        let _ = session.save_to_disk(&state_file);

        let unlocked_gate_idx = session
            .plan
            .gates
            .iter()
            .find(|g| g.status == GateStatus::Unlocked)
            .map(|g| g.gate_index);

        let next_gate_detail = if let Some(idx) = unlocked_gate_idx {
            let raw = self.tool_inspect_gate(&json!({ "gate_index": idx }))?;
            serde_json::from_str::<Value>(&raw).unwrap_or(Value::Null)
        } else {
            Value::Null
        };

        Ok(serde_json::to_string_pretty(&json!({
            "session_phase": new_phase,
            "unlocked_gate": next_gate_detail
        }))?)
    }

    fn tool_rollback(&mut self, args: &Value) -> Result<String> {
        let session = self
            .session
            .as_mut()
            .ok_or_else(|| anyhow!("No active corridor session."))?;

        let to_gate = args
            .get("to_gate_index")
            .and_then(|v| v.as_u64())
            .ok_or_else(|| anyhow!("Missing to_gate_index"))? as usize;

        let reverted = session.rollback_to_gate(to_gate)?;
        let state_file = self.workspace_root.join(".corridor/active_session.json");
        let _ = session.save_to_disk(&state_file);

        let reverted_paths: Vec<String> = reverted.into_iter().map(|(_, rel)| rel).collect();
        Ok(serde_json::to_string_pretty(&json!({
            "rolled_back_to_gate": to_gate,
            "reverted_files": reverted_paths,
            "active_phase": session.phase
        }))?)
    }
}

use crate::tools::CorridorMcpEngine;
use anyhow::Result;
use serde_json::{json, Value};
use std::io::{self, BufRead, Write};

pub struct McpStdioServer {
    engine: CorridorMcpEngine,
}

impl McpStdioServer {
    pub fn new(engine: CorridorMcpEngine) -> Self {
        Self { engine }
    }

    pub fn run_stdio_loop(&mut self) -> Result<()> {
        let stdin = io::stdin();
        let mut stdout = io::stdout();

        for line in stdin.lock().lines() {
            let line = line?;
            if line.trim().is_empty() {
                continue;
            }

            let req: Value = match serde_json::from_str(&line) {
                Ok(v) => v,
                Err(e) => {
                    let err_resp = json!({
                        "jsonrpc": "2.0",
                        "id": null,
                        "error": { "code": -32700, "message": format!("Parse error: {}", e) }
                    });
                    writeln!(stdout, "{}", err_resp)?;
                    stdout.flush()?;
                    continue;
                }
            };

            let id = req.get("id").cloned().unwrap_or(Value::Null);
            let method = req.get("method").and_then(|m| m.as_str()).unwrap_or("");
            let params = req.get("params").cloned().unwrap_or_else(|| json!({}));

            if method.starts_with("notifications/") {
                continue;
            }

            let response = match method {
                "initialize" => json!({
                    "jsonrpc": "2.0",
                    "id": id,
                    "result": {
                        "protocolVersion": "2024-11-05",
                        "capabilities": { "tools": {} },
                        "serverInfo": {
                            "name": "corridor-mcp",
                            "version": "0.1.0"
                        }
                    }
                }),
                "tools/list" => json!({
                    "jsonrpc": "2.0",
                    "id": id,
                    "result": CorridorMcpEngine::list_tool_definitions()
                }),
                "tools/call" => {
                    let tool_name = params.get("name").and_then(|n| n.as_str()).unwrap_or("");
                    let arguments = params.get("arguments").cloned().unwrap_or_else(|| json!({}));

                    match self.engine.dispatch_tool(tool_name, &arguments) {
                        Ok(text_payload) => json!({
                            "jsonrpc": "2.0",
                            "id": id,
                            "result": {
                                "isError": false,
                                "content": [{ "type": "text", "text": text_payload }]
                            }
                        }),
                        Err(err) => json!({
                            "jsonrpc": "2.0",
                            "id": id,
                            "result": {
                                "isError": true,
                                "content": [{ "type": "text", "text": err.to_string() }]
                            }
                        }),
                    }
                }
                _ => json!({
                    "jsonrpc": "2.0",
                    "id": id,
                    "error": { "code": -32601, "message": format!("Method not found: {}", method) }
                }),
            };

            writeln!(stdout, "{}", serde_json::to_string(&response)?)?;
            stdout.flush()?;
        }

        Ok(())
    }
}

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use corridor_core::pruning::PruningConfig;
use corridor_core::slicer::{CorridorSlicer, SliceIntent};
use corridor_mcp::server::McpStdioServer;
use corridor_mcp::tools::CorridorMcpEngine;
use corridor_ts_bridge::scip_loader::ScipGraphBuilder;
use std::path::PathBuf;
use std::process::Command;

#[derive(Parser)]
#[command(name = "corridor", version = "0.1.0", about = "Deterministic Execution & Mutation State-Machine for AI Coding Agents")]
struct Cli {
    #[arg(short, long, default_value = ".")]
    workspace: PathBuf,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Runs scip-typescript on the target repository to generate .corridor/index.scip
    Index,
    /// Deterministically slices a corridor from an Entry Gate and prints JSON plan
    Slice {
        #[arg(short, long)]
        entry: String,
        #[arg(short, long, default_value = "READ_FLOW")]
        intent: String,
        #[arg(short, long)]
        target: Option<String>,
    },
    /// Starts the Stateful MCP Server over stdio for Claude Code / Cursor
    Mcp {
        #[arg(long, default_value_t = false)]
        full_typecheck: bool,
    },
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let workspace = cli.workspace.canonicalize().unwrap_or(cli.workspace);
    let scip_path = workspace.join(".corridor/index.scip");

    match cli.command {
        Commands::Index => {
            std::fs::create_dir_all(workspace.join(".corridor"))?;
            let status = Command::new("npx")
                .args([
                    "@sourcegraph/scip-typescript",
                    "index",
                    "--output",
                    scip_path.to_str().unwrap(),
                ])
                .current_dir(&workspace)
                .status()
                .context("Failed to execute npx @sourcegraph/scip-typescript")?;

            if !status.success() {
                anyhow::bail!("scip-typescript indexing failed");
            }
            println!("Indexed TypeScript semantic graph at {}", scip_path.display());
        }
        Commands::Slice { entry, intent, target } => {
            let graph = ScipGraphBuilder::build_from_scip_file(&workspace, &scip_path)?;
            let slice_intent = if intent == "MUTATE_CONTRACT" {
                SliceIntent::MutateContract
            } else {
                SliceIntent::ReadFlow
            };
            let plan = CorridorSlicer::build_corridor(
                &graph,
                &entry,
                slice_intent,
                target.as_deref(),
                &PruningConfig::default(),
            )?;
            println!("{}", serde_json::to_string_pretty(&plan)?);
        }
        Commands::Mcp { full_typecheck } => {
            let graph = ScipGraphBuilder::build_from_scip_file(&workspace, &scip_path)?;
            let engine = CorridorMcpEngine::new(workspace, graph, full_typecheck);
            let mut server = McpStdioServer::new(engine);
            server.run_stdio_loop()?;
        }
    }

    Ok(())
}
